const correlationId = 'corr_acc_' + Date.now();

const systemPrompt = `Eres el gestor de accountability y recordatorios de RAX.\nTu función es evaluar compromisos en riesgo o vencidos y formular borradores de seguimiento no invasivos.\nREGLAS:\n1. No dispares comunicaciones externas; solo genera borradores de notificación para revisión del mentor.\n2. Distingue entre tareas por vencer y tareas con bloqueo declarado.\n3. Salida en JSON estricto con: reminderDrafts (array de objetos con taskId, recipientRole, messageDraft, urgency), uncertainties (array).`;

const userPrompt = JSON.stringify({
  scheduledRunAt: new Date().toISOString(),
  criteria: 'overdue_or_upcoming_48h'
});

return [{
  json: {
    correlationId,
    callbackUrl: ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Accountability Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { reminderDrafts: [], uncertainties: ['Salida JSON no válida'] };
}

const proposals = (parsed.reminderDrafts || []).map(r => ({
  type: 'intervention',
  title: `Borrador recordatorio: ${r.recipientRole}`,
  description: r.messageDraft,
  ownerSuggestion: 'mentor',
  needsHumanApproval: true,
  uncertainties: []
}));

const callbackPayload = {
  operationId: 'op_acc_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-10',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: `Se prepararon ${proposals.length} borradores de seguimiento para revisión.`,
    proposals,
    uncertainties: parsed.uncertainties || []
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
